def compute_accuracy(preds, labels):
    correct = 0
    for pred, label in zip(preds, labels):
        if pred == label:
            correct += 1
    return correct / len(labels)

def parse_error_line(line):
    if "FileNotFoundError" in line:
        return "missing_file"
    if "Timeout" in line:
        return "timeout"
    return "unknown"

