def select_top_items(items, limit=20):
    items = sorted(items, key=lambda x: x["score"], reverse=True)
    return items[:limit]

def build_reading_queue(candidates):
    queue = []
    for item in candidates:
        if item["domain"] in ["UAM", "AI", "Robotics"]:
            queue.append(item)
    return queue[:10]

def count_by_level(cards):
    counts = {}
    for card in cards:
        level = card["level"]
        counts[level] = counts.get(level, 0) + 1
    return counts

def find_card(cards, card_id):
    for card in cards:
        if card["id"] == card_id:
            return card
    return None

